import json
n=27
g=[[3]*n for _ in range(n)]
pat=[[1,1,1],[4,4,2],[1,4,1],[8]]
# preserve tiny pattern
for i,row in enumerate(pat):
    for j,v in enumerate(row):
        g[1+2*i][1+2*j]=v
# expand the pattern into 4x4 blocks, clipping to the canvas
for i,row in enumerate(pat):
    for j,v in enumerate(row):
        for r in range(10+5*i,min(14+5*i,n)):
            for c in range(13+5*j,min(17+5*j,n)):
                g[r][c]=v
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

